import {allocateRaster} from './image-sampling.mjs';
import {composePixel} from './image-insert.mjs';
import {MseError} from './document.mjs';

// BleedEdgedImage::generate mirrors the next interior pixel at each edge;
// corner pixels are generated by mirroring the already-filled side borders.
export function bleedRaster(source,{horizontal=-1,vertical=-1,background=[0,0,0,0]}={},maxPixels=16777216){
  if(!Number.isFinite(horizontal)||!Number.isFinite(vertical))throw new MseError('image-bleed','Bleed sizes must be finite');
  const w=source.width,h=source.height;
  if(w<=3||h<=3)return source;
  const landscape=w>h;
  const dx=Math.min(w-1,Math.max(0,Math.trunc(w*(horizontal>0?horizontal:landscape?0.037:0.048))));
  const dy=Math.min(h-1,Math.max(0,Math.trunc(h*(vertical>0?vertical:landscape?0.048:0.037))));
  if(!dx&&!dy)return source;
  const width=w+2*dx,height=h+2*dy,out=allocateRaster(width,height,true,maxPixels);
  for(let i=0;i<out.data.length;i+=4)out.data.set(background,i);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++)composePixel(out.data,((y+dy)*width+x+dx)*4,source.data,(y*w+x)*4,source.hasAlpha);
  const copy=(x,y,sx,sy)=>{const from=(sy*width+sx)*4;out.data.set(out.data.subarray(from,from+4),(y*width+x)*4);};
  for(let y=dy;y<dy+h;y++)for(let x=0;x<dx;x++)copy(x,y,2*dx-x,y);
  for(let y=dy;y<dy+h;y++)for(let x=0;x<dx;x++)copy(width-dx+x,y,width-dx-2-x,y);
  for(let y=0;y<dy;y++)for(let x=0;x<width;x++)copy(x,y,x,2*dy-y);
  for(let y=0;y<dy;y++)for(let x=0;x<width;x++)copy(x,height-dy+y,x,height-dy-2-y);
  return out;
}
